// street.js — F 路：街面实时层（路灯亮化 / 街具 / 店面门面 / 街上实时验走法）
// 方案 §3.14 / 验收表第 15 行 + 第 24 行（夜景重做，F 路管路灯亮化）。
// 本轮（对照表 S04/S06/S12）：街面一处一处磨——⑦ 街面生活四组（停放单车 /
//   公交站 / 小吃摊 / 井盖），逐处定点，不满街撒；招牌字只用通用字，无品牌。
// 技能—方法：procedural-gen（种子定点 + 加权选色）；threejs-to-3d-model
// （程序化拼装 + InstancedMesh 合批）；阿哲的方法：数据层（种子/定点）→
// 逐处重建（16 地标门口 + 3 摊 + 2 站逐处定）→ 两套构件库（街面构件库，
// 另一套是 people.js 人物构件库）→ 像素回归（浏览器截图由协调员
// tests/verify-surpass-f.js 跑；本地只做 node 语法 + 计数验算）→ 独立审查再合并。
// 路灯做法（13:50 改向后）：学他那摆放——灯沿路走、两侧交错、等距、夜里全亮。
// 我们的 141,756 盏是实灯：位置只在分块 GLB 的线几何里（CJJ45 间距沿真实 OSM
// 路放置，见 build_six.py:994-1005，灯杆线色 C_LAMP=[0.62,0.62,0.65]），
// six-loader 不暴露灯位列表。本模块运行时直接从已加载分块的线几何里按灯色
// 把实灯位置读出来（灯杆顶端 = 灯头），夜里全部加上发光点——不是另编一套
// 假灯位。参考沙盘灯位间距的具体数字在已读到的文字版/方法里没给，无法核实，
// 不编数字；我们执行的是包里实灯自身的放置规则（CJJ45 间距沿路）。
// 灯杆实体（本轮新增）：主干上的实灯在灯头处立杆——杆（GLB 线位，杆高取线长，
//   地面灯 9.12/8.05m）＋臂（向路中线伸 1.6m）＋头（臂端灯具）；杆/臂/头各一个
//   InstancedMesh。非主干灯本轮只留光点，杆以后扩。光点随之移到臂端，与实体
//   头一致。白模：杆/臂/头进 origInstanceColors，白膜下变白、不消失（几何在）。
// 白模阶段（16:51 令）：本文件新增的都是白模几何，不贴图；颜色只走既有的
// 实例色机制，白膜下一键变白。
// 店面招牌字全部是自己画的通用字（canvas 绘制），无任何真实品牌。
