const scannedRoots = new Set();
let shopSignMats = []; // 每块招牌的材质（昼夜亮度调节用）
let neonMeshes = [];   // 霓虹件（白膜模式要收起来）
let origInstanceColors = new Map(); // mesh.uuid -> Map(index -> hex)
